vec3 shade(Surface s, Light light) {
    vec3 L = normalize(light.position - s.position);
    float NoL = max(dot(normalize(s.normal), L), 0.0);
    return (s.albedo / PI) * light.irradiance * NoL;
}

// 前向片元阶段
Surface s = evaluateMaterial();
vec3 hdr = s.emission;
for (int j = 0; j < relevantLightCount; ++j)
    hdr += shade(s, relevantLights[j]);
outColor = vec4(hdr, 1.0);

// 几何 pass：由材质产生表面记录
G0 = vec4(s.albedo, s.metallic);
G1 = vec4(encodeNormal(s.normal), s.roughness);
// 深度由深度附件保存

// 光照 pass：从屏幕坐标读取记录
Surface s = decodeGBuffer(uv);
s.position = reconstructPosition(uv, depthTexture, inverseViewProjection);
vec3 hdr = s.emission;
for (int j = 0; j < affectingLightCount; ++j)
    hdr += shade(s, affectingLights[j]);

void mainImage(out vec4 O, in vec2 C) {
    vec2 uv = C / iResolution.xy;
    vec3 color = texture(iChannel0, uv).rgb;
    vec2 p = (C - 0.5 * iResolution.xy) / iResolution.y;
    float vignette = 1.0 - 0.3 * clamp(dot(p, p), 0.0, 1.0);
    O = vec4(color * vignette, 1.0);
}
